<script setup>
import {ref,onMounted} from 'vue';
import {api,session,can} from './api.js';
import {resources,permissionFor,displayLabels} from './resources.js';
const environment=import.meta.env.DEV?'本地开发环境':'管理环境';
const data=ref(null),error=ref('');
const metrics=[['phone_models','支持的机型','phone-models'],['designs','Collection 设计','designs'],['graphics','图案素材','graphics'],['orders','服务端订单','orders']];
onMounted(async()=>{try{data.value=await api('admin/dashboard/');}catch(e){error.value=e.message;}});
const date=value=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">YOUR DAILY OVERVIEW</p><h1>工作台概览<span class="greeting-dot">.</span></h1><p class="muted">你好，{{session.user.name}}。从这里开始今天的管理工作。</p></div><span class="quiet-badge"><span class="status-dot"></span> {{environment}}</span></div><el-alert v-if="error" :title="error" type="error"/><template v-if="data"><div class="metrics"><router-link v-for="[key,label,target] in metrics.filter(([key])=>key in data.counts)" :key="key" :to="'/'+target" class="metric"><span>{{label}}</span><strong>{{data.counts[key]}}<small>↗</small></strong><p>查看与管理</p></router-link></div><div class="dashboard-grid"><section class="panel quick-panel"><div class="panel-heading"><h2>常用管理</h2><span>CONTENT & CONFIGURATION</span></div><div class="quick-links"><router-link v-for="key in ['designs','graphics','phone-models','plans'].filter(key=>can(permissionFor(key)))" :key="key" :to="'/'+key"><span class="quick-mark">{{{'designs':'✿','graphics':'✧','phone-models':'▯','plans':'$'}[key]}}</span><div><strong>{{resources[key].title}}</strong><p>{{{'designs':'维护完整设计方案','graphics':'整理贴纸与图片','phone-models':'按品牌管理机型','plans':'管理打印与订阅价格'}[key]}}</p></div><span>→</span></router-link></div></section><section class="integration-panel"><p class="eyebrow">CONNECTION STATUS</p><h2>管理数据，<br>已独立存储。</h2><p>下单、价格、AI 次数、风格与案例已接通。保存配置后，刷新用户端即可生效。机型、图库和图案仍使用现有演示目录。</p><div><span>后台数据库</span><b>已连接</b></div><div><span>价格 / AI 案例同步</span><b>已连接</b></div><div><span>订单与设计快照</span><b>已连接 · 测试支付</b></div><div><span>支付 / AI / 打印设备</span><span>待接入</span></div></section></div><section v-if="can('management_api.view_auditlog')" class="panel activity-panel"><div class="panel-heading"><h2>最近操作</h2><router-link to="/audit-logs">查看全部 →</router-link></div><el-table :data="data.activity" empty-text="还没有操作记录"><el-table-column prop="actor_name" label="操作人" width="150"/><el-table-column label="动作" width="100"><template #default="{row}"><span class="action-chip">{{displayLabels[row.action]||row.action}}</span></template></el-table-column><el-table-column prop="summary" label="内容"/><el-table-column label="时间" width="160"><template #default="{row}">{{date(row.created_at)}}</template></el-table-column></el-table></section></template><el-skeleton v-else-if="!error" :rows="9" animated/></section></template>
